algorithms/ddmin.yaml.pseudocode:
current = all_groups
granularity = 2
while size(current) >= 2:
  candidates = complements_and_subsets(current, granularity)
  passing = first candidate where oracle(candidate) == PASS
  if passing exists: current = passing; granularity = max(granularity - 1, 2)
  else if granularity < size(current): granularity = min(size(current), granularity * 2)
  else: break
return current
